  do{++polls;observed=physical(display,window);if(observed.rgba.size()==alone.rgba.size()&&(geometry?composite(scene,alone,observed,samples,true,false):rgbEqual(alone,observed))){std::cout<<"raster_msaa_physical kind="<<scene.kind<<" N="<<samples<<" polls="<<polls<<" geometry="<<geometry<<'\n';return true;}std::this_thread::sleep_for(std::chrono::milliseconds(5));}while(std::chrono::steady_clock::now()<until);
